import anthropic


def sum_two_numbers(a: int | float, b: int | float) -> int | float:
    """
    Returns the sum of two numbers using Claude AI.

    Args:
        a: First number
        b: Second number

    Returns:
        The sum of a and b
    """
    client = anthropic.Anthropic()

    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {
                "role": "user",
                "content": f"What is {a} + {b}? Please respond with only the numerical result."
            }
        ]
    )

    result_text = message.content[0].text.strip()

    try:
        if '.' in result_text:
            return float(result_text)
        else:
            return int(result_text)
    except ValueError:
        return float(result_text)


if __name__ == "__main__":
    result1 = sum_two_numbers(5, 3)
    print(f"5 + 3 = {result1}")

    result2 = sum_two_numbers(10.5, 2.3)
    print(f"10.5 + 2.3 = {result2}")

    result3 = sum_two_numbers(-5, 8)
    print(f"-5 + 8 = {result3}")

def is_prime(n: int) -> bool:
    """
    Check if a number is prime.

    Args:
        n: The number to check

    Returns:
        True if the number is prime, False otherwise
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Check odd divisors up to sqrt(n)
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_maximum(numbers):
    """Find the maximum number in a list."""
    if not numbers:
        return None
    return max(numbers)

import anthropic


def fibonacci(n: int) -> int:
    """
    Returns the Fibonacci number at index n using Claude AI.

    Args:
        n: The index of the Fibonacci number to return (0-indexed)

    Returns:
        The Fibonacci number at index n
    """
    client = anthropic.Anthropic()

    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {
                "role": "user",
                "content": f"What is the Fibonacci number at index {n}? Please respond with only the number, no explanation."
            }
        ]
    )

    result = message.content[0].text.strip()
    return int(result)


if __name__ == "__main__":
    for i in range(10):
        print(f"Fibonacci({i}) = {fibonacci(i)}")

def remove_duplicates(lst):
    """Remove duplicates from a list while preserving order."""
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result
